            {
              "note_id": "FCT_0026",
              "exact_quote": "The return type of a function is specified first."
            },
            {
              "note_id": "FCT_0028",
              "exact_quote": "The return type of functions that do not return a value is void."
            },
            {
              "note_id": "FCT_0030",
              "exact_quote": "After the return type, the name of the function appears."
            },
            {
              "note_id": "FCT_0033",
              "exact_quote": "After the function name, parentheses contain the parameters for the function."
            },
            {
              "note_id": "FCT_0034",
              "exact_quote": "Parameters are used to pass values to a function."
            }
